import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.yo2CxoV2.js";const m=JSON.parse('{"title":"ordloom-payments 支付管理","description":"","frontmatter":{},"headers":[],"relativePath":"guides/payments.md","filePath":"guides/payments.md","lastUpdated":1794723217000}'),i={name:"guides/payments.md"};function d(n,e,r,l,c,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ordloom-payments-支付管理" tabindex="-1">ordloom-payments 支付管理 <a class="header-anchor" href="#ordloom-payments-支付管理" aria-label="Permalink to &quot;ordloom-payments 支付管理&quot;">​</a></h1><p><code>ordloom-payments</code> 0.1.0 是商城交易闭环的独立子应用：订单支付交易、人工确认或宿主适配器确认、退款补偿与对账任务。要求 Python 3.9+、Django 4.2+、<code>ordloom&gt;=1.1.0,&lt;2</code> 与 <code>ordloom-shop&gt;=0.1.0,&lt;0.2</code>（单商户、CNY）。Ordloom 1.2.1 的应用目录包含其接入信息。</p><h2 id="安装与接入" tabindex="-1">安装与接入 <a class="header-anchor" href="#安装与接入" aria-label="Permalink to &quot;安装与接入&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2.1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom-shop==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom-payments==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1.0</span></span></code></pre></div><p>注册 <code>ordloom_payments.apps.ExtensionConfig</code>，显式挂载 <code>include(&quot;ordloom_payments.urls&quot;)</code> 并执行 <code>migrate</code>。<code>ORDLOOM_PAYMENTS={&quot;enabled&quot;:True}</code> 默认关闭。会员从 <code>/payments/api/v1/payments/</code>（POST <code>order</code>+<code>request_key</code>）为本人待支付订单创建交易；重放同一 <code>request_key</code> 返回原交易，金额始终以商城服务端核价为准。</p><h2 id="渠道与语义" tabindex="-1">渠道与语义 <a class="header-anchor" href="#渠道与语义" aria-label="Permalink to &quot;渠道与语义&quot;">​</a></h2><ul><li><strong>人工确认模式（默认）</strong>：不配置 <code>provider</code> 时，具备 <code>confirm_payment</code> 权限的管理员在后台动作「确认支付/标记失败」，退款通过 <code>request_refund</code> 权限后台确认。适合线下转账、对公入账等人工渠道。</li><li><strong>适配器模式</strong>：<code>ORDLOOM_PAYMENTS[&quot;provider&quot;]=&quot;myproject.payments.Adapter&quot;</code> 声明实现 <code>create_payment(transaction)</code>、<code>verify_callback(request)</code>、<code>query_status(transaction)</code>、<code>refund(refund)</code> 的适配器；回调端点 <code>/payments/callback/</code> 仅在配置适配器后开放，<strong>验签由适配器负责</strong>，事件唯一键在数据库层面防重放。同一订单同时只有一笔进行中支付。</li><li><strong>订单衔接</strong>：支付完成不直写订单状态——对账任务 <code>ext:payments.reconcile</code> 由宿主调度，复核当前权限后复用商城 <code>services.transition(...,&#39;confirm&#39;)</code> 确认订单；退款补偿同样按任务推进。库存归还仍由商城取消/超时路径唯一保证。</li><li>管理沿用 Django 模型/对象权限与 <code>ModelAdmin.get_queryset</code> 范围；<code>provider_ref</code> 仅对 staff 序列化。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单商户/CNY、无多币种、无分账/发票/对账文件导出；<code>verify_callback</code> 的安全实现与真实支付平台联调、资金对账、纠纷处理属于启用前验收；适配器代码为可信宿主代码，不存在在线渠道配置或沙箱。完整指南见 <a href="https://neekin.github.io/ordloom-docs/guides/payments.html" target="_blank" rel="noreferrer">https://neekin.github.io/ordloom-docs/guides/payments.html</a> 。</p>',9)])])}const u=o(i,[["render",d]]);export{m as __pageData,u as default};
